import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'pg-admin-l2-001', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What does VACUUM do in PostgreSQL?', options: ['Reclaims storage from dead tuples (rows deleted or obsoleted by updates) and makes it available for reuse — it also updates visibility maps and statistics used by the query planner', 'Defragments the hard disk', 'Compresses table data', 'Removes unused indexes'], correctAnswer: 0, explanation: 'PostgreSQL uses MVCC, so DELETE and UPDATE leave dead tuples. VACUUM marks the space occupied by dead tuples as available for reuse. It also updates the visibility map (for index-only scans) and optionally updates planner statistics. Without regular vacuuming, tables bloat.', codeSnippet: "-- Vacuum a specific table:\nVACUUM employees;\n\n-- Vacuum with verbose output:\nVACUUM VERBOSE employees;\n\n-- Vacuum entire database:\nVACUUM;\n\n-- Check dead tuples before vacuum:\nSELECT relname, n_dead_tup, last_vacuum, last_autovacuum\nFROM pg_stat_user_tables\nWHERE n_dead_tup > 0\nORDER BY n_dead_tup DESC;", tags: ['admin', 'vacuum', 'maintenance'] },
  { id: 'pg-admin-l2-002', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is the difference between VACUUM and VACUUM FULL?', options: ['VACUUM FULL is just a verbose version', 'VACUUM reclaims space for reuse within the table; VACUUM FULL rewrites the entire table to reclaim space back to the OS — it requires an exclusive lock and more disk space', 'VACUUM FULL only vacuums indexes', 'There is no difference'], correctAnswer: 1, explanation: 'Regular VACUUM marks dead tuple space as reusable but does not shrink the table file. VACUUM FULL rewrites the table to a new file, physically reclaiming disk space, but requires an ACCESS EXCLUSIVE lock (blocks all reads/writes) and temporary disk space for the new copy.', codeSnippet: "-- Regular VACUUM: non-blocking, reclaims for reuse\nVACUUM orders;\n-- Table file size unchanged, space reusable internally\n\n-- VACUUM FULL: blocking, shrinks table on disk\nVACUUM FULL orders;\n-- Table rewritten, disk space returned to OS\n-- WARNING: locks table exclusively!\n\n-- Alternative to VACUUM FULL (non-blocking):\n-- Use pg_repack extension for online table compaction", tags: ['admin', 'vacuum', 'vacuum-full', 'maintenance'] },
  { id: 'pg-admin-l2-003', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'ANALYZE', question: 'What does the ANALYZE command do?', options: ['Analyzes SQL syntax', 'Collects statistics about table contents (column value distribution, most common values, correlation) and stores them in pg_statistic for the query planner to make optimal decisions', 'Analyzes disk usage', 'Checks for data corruption'], correctAnswer: 1, explanation: 'ANALYZE samples table data and computes statistics including most common values, histograms, null fractions, and average column widths. The query planner uses these statistics to estimate row counts and choose optimal join strategies, scan methods, and sort algorithms.', codeSnippet: "-- Analyze a specific table:\nANALYZE employees;\n\n-- Analyze specific columns:\nANALYZE employees (department, salary);\n\n-- Analyze all tables in database:\nANALYZE;\n\n-- Analyze with verbose output:\nANALYZE VERBOSE employees;\n\n-- Check when last analyzed:\nSELECT relname, last_analyze, last_autoanalyze\nFROM pg_stat_user_tables;", tags: ['admin', 'analyze', 'statistics', 'planner'] },
  { id: 'pg-admin-l2-004', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is autovacuum and why is it important?', options: ['A manual vacuum schedule', 'An automatic background process that runs VACUUM and ANALYZE on tables when dead tuple counts or row modifications exceed configurable thresholds — it prevents table bloat and keeps statistics current', 'A third-party tool for vacuuming', 'An operating system feature'], correctAnswer: 1, explanation: 'Autovacuum is a built-in daemon that monitors tables and automatically runs VACUUM and ANALYZE when needed. It triggers based on dead tuple thresholds (autovacuum_vacuum_threshold + scale_factor * reltuples). Disabling it leads to table bloat, stale statistics, and eventually transaction ID wraparound.', codeSnippet: "-- Check autovacuum settings:\nSHOW autovacuum;\nSHOW autovacuum_vacuum_threshold;      -- 50\nSHOW autovacuum_vacuum_scale_factor;    -- 0.2\nSHOW autovacuum_analyze_threshold;      -- 50\nSHOW autovacuum_analyze_scale_factor;   -- 0.1\n\n-- Check autovacuum activity:\nSELECT relname, last_autovacuum, last_autoanalyze,\n       autovacuum_count, autoanalyze_count\nFROM pg_stat_user_tables;", tags: ['admin', 'autovacuum', 'maintenance'] },
  { id: 'pg-admin-l2-005', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What information does pg_stat_user_tables provide?', options: ['User table definitions', 'Runtime statistics per table including sequential/index scan counts, rows returned, insert/update/delete counts, dead tuples, and last vacuum/analyze timestamps', 'User permissions on tables', 'Table creation dates'], correctAnswer: 1, explanation: 'pg_stat_user_tables shows cumulative statistics for each user table: scan counts (seq_scan, idx_scan), tuple operations (n_tup_ins, n_tup_upd, n_tup_del), dead tuple count (n_dead_tup), and maintenance timestamps (last_vacuum, last_analyze). Essential for monitoring table health.', codeSnippet: "-- Tables with most sequential scans (potential missing indexes):\nSELECT relname, seq_scan, seq_tup_read,\n       idx_scan, n_live_tup\nFROM pg_stat_user_tables\nWHERE seq_scan > 100\nORDER BY seq_tup_read DESC;\n\n-- Tables needing vacuum:\nSELECT relname, n_dead_tup, n_live_tup,\n       round(100.0 * n_dead_tup / NULLIF(n_live_tup, 0), 1) AS dead_pct\nFROM pg_stat_user_tables\nWHERE n_dead_tup > 1000\nORDER BY n_dead_tup DESC;", tags: ['admin', 'pg-stat', 'monitoring', 'tables'] },
  { id: 'pg-admin-l2-006', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'What are the three main types of PostgreSQL backup strategies?', options: ['Hot, warm, and cold backups', 'SQL dump (pg_dump), file system level backup, and continuous archiving (WAL archiving with pg_basebackup) — each has different trade-offs for speed, granularity, and recovery options', 'Full, differential, and incremental', 'Online, offline, and snapshot'], correctAnswer: 1, explanation: 'SQL dump (logical) is portable and granular but slower for large databases. File system backup copies the data directory but requires the server to be stopped or use a snapshot. Continuous archiving (physical) uses pg_basebackup + WAL archiving for point-in-time recovery and is best for large databases.', tags: ['admin', 'backup', 'strategies'] },
  { id: 'pg-admin-l2-007', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Tablespaces', question: 'What is a tablespace in PostgreSQL?', options: ['A synonym for schema', 'A location on the file system where PostgreSQL stores data files — allows distributing database objects across different physical disks or storage tiers', 'A namespace for tables', 'A memory region for caching tables'], correctAnswer: 1, explanation: 'Tablespaces map database objects to file system locations. By default, PostgreSQL uses pg_default and pg_global. Custom tablespaces allow placing frequently accessed tables on fast SSDs and archive data on slower disks. They are defined at the cluster level.', codeSnippet: "-- Create a tablespace on fast SSD:\nCREATE TABLESPACE fast_storage\n  LOCATION '/mnt/ssd/pgdata';\n\n-- Create a table in the tablespace:\nCREATE TABLE hot_data (\n  id SERIAL PRIMARY KEY, data JSONB\n) TABLESPACE fast_storage;\n\n-- Move existing table to a tablespace:\nALTER TABLE orders SET TABLESPACE fast_storage;\n\n-- List tablespaces:\n\\db\nSELECT spcname, pg_size_pretty(pg_tablespace_size(oid))\nFROM pg_tablespace;", tags: ['admin', 'tablespaces', 'storage'] },
  { id: 'pg-admin-l2-008', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is transaction ID wraparound and why is VACUUM needed to prevent it?', options: ['A performance optimization', 'PostgreSQL uses 32-bit transaction IDs with wraparound semantics — VACUUM must periodically freeze old tuples to prevent the counter from wrapping around, which would make old data appear to be from the future and become invisible', 'A replication mechanism', 'A connection pooling feature'], correctAnswer: 1, explanation: 'PostgreSQL uses 32-bit transaction IDs (~4 billion). When the counter wraps, old unfrozen transactions would appear to be in the future, making data invisible. VACUUM freezes tuples older than vacuum_freeze_min_age, marking them as visible to all transactions regardless of XID.', codeSnippet: "-- Check transaction age per database:\nSELECT datname,\n  age(datfrozenxid) AS xid_age,\n  current_setting('autovacuum_freeze_max_age') AS max_age\nFROM pg_database\nORDER BY age(datfrozenxid) DESC;\n\n-- Tables closest to wraparound:\nSELECT relname, age(relfrozenxid) AS xid_age\nFROM pg_class\nWHERE relkind = 'r'\nORDER BY age(relfrozenxid) DESC\nLIMIT 10;\n\n-- Force aggressive freeze:\nVACUUM FREEZE large_table;", tags: ['admin', 'vacuum', 'transaction-wraparound', 'freeze'] },
  { id: 'pg-admin-l2-009', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What does pg_stat_user_indexes tell you?', options: ['Index definitions', 'Statistics about index usage including scan count and tuples fetched — helps identify unused indexes that waste storage and slow down writes', 'Index creation history', 'Index compression ratios'], correctAnswer: 1, explanation: 'pg_stat_user_indexes shows per-index statistics: idx_scan (number of index scans), idx_tup_read (index entries read), and idx_tup_fetch (live table rows fetched). Indexes with idx_scan = 0 over a long period are candidates for removal.', codeSnippet: "-- Find unused indexes:\nSELECT relname AS table, indexrelname AS index,\n       idx_scan, pg_size_pretty(pg_relation_size(indexrelid)) AS size\nFROM pg_stat_user_indexes\nWHERE idx_scan = 0\nORDER BY pg_relation_size(indexrelid) DESC;\n\n-- Most used indexes:\nSELECT indexrelname, idx_scan, idx_tup_read, idx_tup_fetch\nFROM pg_stat_user_indexes\nORDER BY idx_scan DESC\nLIMIT 20;", tags: ['admin', 'pg-stat', 'indexes', 'monitoring'] },
  { id: 'pg-admin-l2-010', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'What is the advantage of custom format (-Fc) over plain SQL format for pg_dump?', options: ['Custom format is human-readable', 'Custom format supports compression, parallel restore, selective restore of specific objects, and reordering of data — plain SQL format supports none of these', 'Plain format is deprecated', 'Custom format is smaller without compression'], correctAnswer: 1, explanation: 'Custom format (-Fc) archives are: (1) compressed by default (zlib), (2) support parallel restore with -j workers, (3) allow selective restore of specific tables/schemas, (4) can reorder the table of contents for restore optimization. Plain SQL dumps require sequential processing.', codeSnippet: "# Custom format dump:\npg_dump -Fc mydb > backup.dump\n\n# Advantages:\n# 1. Compressed by default\n# 2. Parallel restore:\npg_restore -d mydb -j 4 backup.dump\n\n# 3. Selective restore:\npg_restore -d mydb -t orders backup.dump\npg_restore -d mydb -n sales backup.dump  # specific schema\n\n# 4. List and reorder contents:\npg_restore -l backup.dump > toc.txt\n# Edit toc.txt\npg_restore -d mydb -L toc.txt backup.dump", tags: ['admin', 'backup', 'custom-format', 'pg-dump'] },
  { id: 'pg-admin-l2-011', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is the visibility map and how does VACUUM update it?', options: ['A map of visible schemas', 'A per-table bitmap where each bit tracks whether all tuples on a page are visible to all transactions — VACUUM sets bits for fully-visible pages, enabling index-only scans and skipping known-clean pages in future vacuums', 'A map of user permissions', 'A network visibility diagram'], correctAnswer: 1, explanation: 'The visibility map (VM) has one bit per heap page indicating whether all tuples on that page are visible to all current and future transactions. VACUUM sets these bits. Index-only scans use the VM to avoid visiting the heap for confirmed-visible pages. Subsequent vacuums skip pages marked as all-visible.', codeSnippet: "-- Check visibility map coverage:\nSELECT relname,\n  pg_size_pretty(pg_relation_size(oid)) AS size,\n  n_live_tup, n_dead_tup\nFROM pg_class\nJOIN pg_stat_user_tables USING (relname)\nWHERE relkind = 'r'\nORDER BY n_dead_tup DESC;\n\n-- Visibility map extension for analysis:\nCREATE EXTENSION pg_visibility;\nSELECT * FROM pg_visibility('orders');", tags: ['admin', 'vacuum', 'visibility-map', 'index-only-scan'] },
  { id: 'pg-admin-l2-012', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'ANALYZE', question: 'What is the default_statistics_target setting?', options: ['The number of tables to analyze', 'Controls the number of values sampled per column during ANALYZE — higher values produce more accurate statistics for the planner but increase ANALYZE time and pg_statistic size; default is 100', 'The target number of queries to optimize', 'The number of concurrent analyzers'], correctAnswer: 1, explanation: 'default_statistics_target (default 100) controls the histogram bucket count and most-common-values list size. Higher values (up to 10000) improve planner estimates for columns with many distinct values or skewed distributions, at the cost of slower ANALYZE and more catalog storage.', codeSnippet: "-- Check current setting:\nSHOW default_statistics_target;  -- 100\n\n-- Set higher target for a specific column:\nALTER TABLE orders ALTER COLUMN status\n  SET STATISTICS 500;\n\n-- Then re-analyze:\nANALYZE orders;\n\n-- View collected statistics:\nSELECT attname, n_distinct, most_common_vals\nFROM pg_stats\nWHERE tablename = 'orders' AND attname = 'status';", tags: ['admin', 'analyze', 'statistics-target', 'planner'] },
  { id: 'pg-admin-l2-013', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What does pg_stat_bgwriter show?', options: ['Background worker processes', 'Statistics about the background writer process including buffers written by checkpoints, the bgwriter, and backends — helps diagnose I/O and checkpoint performance', 'Background job schedules', 'Background query execution times'], correctAnswer: 1, explanation: 'pg_stat_bgwriter tracks: checkpoints_timed/req (scheduled vs forced checkpoints), buffers_checkpoint/clean/backend (who wrote buffers), and maxwritten_clean (bgwriter stopping due to max pages). High buffers_backend indicates the bgwriter is falling behind.', codeSnippet: "SELECT\n  checkpoints_timed, checkpoints_req,\n  buffers_checkpoint, buffers_clean, buffers_backend,\n  maxwritten_clean,\n  buffers_alloc\nFROM pg_stat_bgwriter;\n\n-- High buffers_backend = bgwriter falling behind\n-- High checkpoints_req = too many forced checkpoints\n-- Tune: bgwriter_lru_maxpages, bgwriter_lru_multiplier\n-- Tune: checkpoint_timeout, max_wal_size", tags: ['admin', 'pg-stat', 'bgwriter', 'checkpoints'] },
  { id: 'pg-admin-l2-014', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Tablespaces', question: 'Can you move an existing table to a different tablespace?', options: ['No, tablespace is fixed at creation', 'Yes — ALTER TABLE tablename SET TABLESPACE new_space; this rewrites the table to the new location and requires an ACCESS EXCLUSIVE lock', 'Only by recreating the table', 'Only with pg_repack'], correctAnswer: 1, explanation: 'ALTER TABLE ... SET TABLESPACE moves a table to a different tablespace. This physically copies all data to the new location. It requires an ACCESS EXCLUSIVE lock during the copy, blocking all access. For indexes, use ALTER INDEX ... SET TABLESPACE.', codeSnippet: "-- Move table to SSD tablespace:\nALTER TABLE orders SET TABLESPACE fast_ssd;\n\n-- Move all indexes of a table:\nALTER INDEX orders_pkey SET TABLESPACE fast_ssd;\nALTER INDEX idx_orders_date SET TABLESPACE fast_ssd;\n\n-- Move entire database to a tablespace:\nALTER DATABASE mydb SET TABLESPACE fast_ssd;\n\n-- Check current tablespace:\nSELECT tablename, tablespace\nFROM pg_tables\nWHERE schemaname = 'public';", tags: ['admin', 'tablespaces', 'move-table'] },
  { id: 'pg-admin-l2-015', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What does VACUUM ANALYZE do?', options: ['Analyzes vacuum logs', 'Runs VACUUM followed by ANALYZE in a single command — reclaims dead tuples and then updates planner statistics', 'Analyzes what needs vacuuming', 'Only analyzes without vacuuming'], correctAnswer: 1, explanation: 'VACUUM ANALYZE combines both operations: first it vacuums (reclaims dead tuple space), then it analyzes (updates statistics). This is a convenient single command for routine maintenance, and autovacuum essentially runs this combination.', codeSnippet: "-- Vacuum and analyze a table:\nVACUUM ANALYZE orders;\n\n-- Vacuum and analyze entire database:\nVACUUM ANALYZE;\n\n-- Verbose output:\nVACUUM (VERBOSE, ANALYZE) orders;\n\n-- Autovacuum effectively does this automatically\n-- when thresholds are exceeded", tags: ['admin', 'vacuum', 'analyze', 'maintenance'] },
  { id: 'pg-admin-l2-016', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'What is the directory format (-Fd) for pg_dump?', options: ['A format for dumping directories', 'Outputs the dump as a directory of files — one per table plus a table of contents; supports parallel dump (-j) and parallel restore', 'A format for dumping only directory paths', 'Deprecated in favor of custom format'], correctAnswer: 1, explanation: 'Directory format creates a directory containing one compressed file per table, plus a table of contents (toc.dat). It supports parallel dump (-j workers) — each worker dumps a different table simultaneously. Combined with parallel restore, this provides the fastest backup/restore for large databases.', codeSnippet: "# Parallel dump (4 workers):\npg_dump -Fd -j 4 mydb -f backup_dir/\n\n# Directory contents:\n# backup_dir/toc.dat     - table of contents\n# backup_dir/1234.dat.gz - table data files\n# backup_dir/1235.dat.gz - ...\n\n# Parallel restore:\npg_restore -d mydb -j 4 backup_dir/\n\n# Selective restore:\npg_restore -d mydb -t orders backup_dir/", tags: ['admin', 'backup', 'directory-format', 'parallel'] },
  { id: 'pg-admin-l2-017', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'How do you find long-running queries using pg_stat_activity?', options: ['Use SHOW QUERIES', 'Query pg_stat_activity filtering by state = \'active\' and ordering by query_start — the duration is now() - query_start', 'Use pg_stat_long_queries', 'Use EXPLAIN on all queries'], correctAnswer: 1, explanation: 'pg_stat_activity shows all active sessions. Filter by state = \'active\' for running queries. The duration is calculated as now() - query_start. Also check state = \'idle in transaction\' for sessions holding locks without executing queries.', codeSnippet: "-- Long-running active queries:\nSELECT pid, usename, datname,\n  now() - query_start AS duration,\n  state, query\nFROM pg_stat_activity\nWHERE state = 'active'\n  AND now() - query_start > interval '5 minutes'\nORDER BY duration DESC;\n\n-- Idle in transaction (holding locks):\nSELECT pid, usename,\n  now() - xact_start AS tx_duration,\n  query\nFROM pg_stat_activity\nWHERE state = 'idle in transaction'\nORDER BY tx_duration DESC;", tags: ['admin', 'pg-stat', 'long-running', 'monitoring'] },
  { id: 'pg-admin-l2-018', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'ANALYZE', question: 'How does autovacuum determine when to run ANALYZE?', options: ['On a fixed schedule', 'When the number of changed tuples (inserts + updates + deletes) since last analyze exceeds autovacuum_analyze_threshold + autovacuum_analyze_scale_factor * estimated row count', 'After every 100 queries', 'Only when manually triggered'], correctAnswer: 1, explanation: 'Autovacuum triggers ANALYZE when: changed_tuples > threshold + scale_factor * reltuples. Defaults are threshold=50 and scale_factor=0.1 (10%). For a table with 100,000 rows, ANALYZE triggers after 10,050 changes. This can be tuned per-table.', codeSnippet: "-- Default thresholds:\nSHOW autovacuum_analyze_threshold;      -- 50\nSHOW autovacuum_analyze_scale_factor;   -- 0.1\n\n-- For a table with 1M rows:\n-- trigger = 50 + 0.1 * 1,000,000 = 100,050 changes\n\n-- Set per-table thresholds for high-churn table:\nALTER TABLE hot_table SET (\n  autovacuum_analyze_threshold = 100,\n  autovacuum_analyze_scale_factor = 0.01  -- 1%\n);", tags: ['admin', 'autovacuum', 'analyze', 'thresholds'] },
  { id: 'pg-admin-l2-019', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Tablespaces', question: 'What are the default tablespaces in PostgreSQL?', options: ['Only pg_default', 'pg_default (for user data) and pg_global (for cluster-wide shared system catalogs) — these cannot be dropped', 'public and private', 'system and user'], correctAnswer: 1, explanation: 'pg_default is the default tablespace for user data (the base directory). pg_global stores cluster-wide objects like pg_database, pg_authid, and shared catalog tables. Both are created by initdb and cannot be dropped. The default tablespace for a database can be changed.', codeSnippet: "-- List tablespaces:\nSELECT spcname, pg_tablespace_location(oid),\n  pg_size_pretty(pg_tablespace_size(spcname))\nFROM pg_tablespace;\n\n-- Change default tablespace for a database:\nALTER DATABASE mydb SET TABLESPACE new_space;\n\n-- Set default tablespace for current session:\nSET default_tablespace = 'fast_ssd';", tags: ['admin', 'tablespaces', 'pg-default', 'pg-global'] },
  { id: 'pg-admin-l2-020', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What are the main autovacuum tuning parameters?', options: ['Only autovacuum_enabled', 'autovacuum_vacuum_threshold, autovacuum_vacuum_scale_factor, autovacuum_vacuum_cost_delay, autovacuum_vacuum_cost_limit, autovacuum_max_workers, and autovacuum_naptime', 'Only max_connections and shared_buffers', 'vacuum_speed and vacuum_threads'], correctAnswer: 1, explanation: 'Key parameters: threshold + scale_factor control when vacuum triggers; cost_delay and cost_limit control how aggressively it runs (I/O throttling); max_workers controls parallelism; naptime controls check frequency. These can be set globally or per-table.', codeSnippet: "-- Global settings:\nSHOW autovacuum_naptime;              -- 1min\nSHOW autovacuum_max_workers;          -- 3\nSHOW autovacuum_vacuum_threshold;     -- 50\nSHOW autovacuum_vacuum_scale_factor;  -- 0.2\nSHOW autovacuum_vacuum_cost_delay;    -- 2ms\nSHOW autovacuum_vacuum_cost_limit;    -- -1 (use vacuum_cost_limit)\n\n-- Per-table override for high-churn table:\nALTER TABLE events SET (\n  autovacuum_vacuum_scale_factor = 0.01,\n  autovacuum_vacuum_threshold = 1000,\n  autovacuum_vacuum_cost_delay = 0  -- no throttling\n);", tags: ['admin', 'autovacuum', 'tuning'] },
  { id: 'pg-admin-l2-021', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What does pg_stat_database show?', options: ['Database creation info', 'Per-database statistics including transaction commit/rollback counts, blocks read/hit (buffer cache ratio), temp file usage, and deadlock counts', 'Database permissions', 'Database replication status'], correctAnswer: 1, explanation: 'pg_stat_database provides aggregated statistics per database: numbackends (connections), xact_commit/xact_rollback (transaction counts), blks_read/blks_hit (I/O), temp_files/temp_bytes (temp usage), deadlocks, and conflict counts. blks_hit / (blks_hit + blks_read) gives the buffer cache hit ratio.', codeSnippet: "-- Cache hit ratio per database:\nSELECT datname,\n  blks_hit, blks_read,\n  CASE WHEN blks_hit + blks_read > 0\n    THEN round(100.0 * blks_hit / (blks_hit + blks_read), 2)\n    ELSE 0\n  END AS cache_hit_pct\nFROM pg_stat_database\nWHERE datname = current_database();\n\n-- Transaction stats:\nSELECT datname, xact_commit, xact_rollback,\n  deadlocks, temp_files, temp_bytes\nFROM pg_stat_database;", tags: ['admin', 'pg-stat', 'database', 'cache-hit-ratio'] },
  { id: 'pg-admin-l2-022', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'How do you perform a parallel dump using pg_dump?', options: ['pg_dump --parallel mydb', 'Use directory format with -j workers: pg_dump -Fd -j 4 mydb -f backup_dir/', 'pg_dump --threads 4 mydb', 'Not possible with pg_dump'], correctAnswer: 1, explanation: 'Parallel dump requires directory format (-Fd) with -j specifying the number of worker processes. Each worker dumps a different table simultaneously. This can dramatically speed up dumps of databases with many large tables.', codeSnippet: "# Parallel dump with 4 workers:\npg_dump -Fd -j 4 mydb -f backup_dir/\n\n# Monitor dump progress:\nls -la backup_dir/\n\n# Parallel restore:\npg_restore -d mydb -j 4 backup_dir/\n\n# Note: -j requires directory format\n# Custom format only supports parallel restore, not dump", tags: ['admin', 'backup', 'parallel-dump', 'pg-dump'] },
  { id: 'pg-admin-l2-023', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is the cost-based vacuum delay?', options: ['The financial cost of vacuuming', 'A throttling mechanism that pauses VACUUM after accumulating a configurable I/O cost — controlled by vacuum_cost_delay and vacuum_cost_limit to reduce the impact on concurrent queries', 'The time cost of analyzing tables', 'A delay before vacuum starts'], correctAnswer: 1, explanation: 'Each I/O operation during vacuum has a cost (vacuum_cost_page_hit=1, vacuum_cost_page_miss=2, vacuum_cost_page_dirty=20). When accumulated cost reaches vacuum_cost_limit (default 200), vacuum sleeps for vacuum_cost_delay (default 0ms). Autovacuum uses its own settings to reduce I/O impact.', codeSnippet: "-- Vacuum cost settings:\nSHOW vacuum_cost_delay;       -- 0 (manual vacuum: no delay)\nSHOW vacuum_cost_limit;       -- 200\nSHOW vacuum_cost_page_hit;    -- 1\nSHOW vacuum_cost_page_miss;   -- 2\nSHOW vacuum_cost_page_dirty;  -- 20\n\n-- Autovacuum cost settings (separate):\nSHOW autovacuum_vacuum_cost_delay;  -- 2ms\nSHOW autovacuum_vacuum_cost_limit;  -- -1 (use vacuum_cost_limit)\n\n-- Make autovacuum more aggressive:\nALTER TABLE hot_table SET (\n  autovacuum_vacuum_cost_delay = 0\n);", tags: ['admin', 'vacuum', 'cost-based', 'throttling'] },
  { id: 'pg-admin-l2-024', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'ANALYZE', question: 'What are extended statistics and when do you need them?', options: ['Statistics for extended data types', 'Multi-column statistics (CREATE STATISTICS) that capture correlations between columns — needed when the planner assumes column independence but columns are actually correlated, causing poor row estimates', 'Extended disk usage statistics', 'Statistics from external databases'], correctAnswer: 1, explanation: 'By default, PostgreSQL collects statistics per column independently. When columns are correlated (e.g., city and zip code), the planner underestimates selectivity. CREATE STATISTICS defines multi-column statistics (ndistinct, dependencies, mcv) that capture these correlations.', codeSnippet: "-- Create multi-column statistics:\nCREATE STATISTICS stts_city_zip (dependencies, ndistinct, mcv)\n  ON city, zip_code FROM addresses;\n\n-- Re-analyze to collect:\nANALYZE addresses;\n\n-- View extended statistics:\nSELECT stxname, stxkeys, stxkind\nFROM pg_statistic_ext;\n\n-- The planner now considers city/zip correlation\n-- for queries like:\nSELECT * FROM addresses\nWHERE city = 'Berlin' AND zip_code = '10115';", tags: ['admin', 'analyze', 'extended-statistics', 'multicolumn'] },
  { id: 'pg-admin-l2-025', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'How do you reset cumulative statistics in pg_stat views?', options: ['RESET STATISTICS', 'Call pg_stat_reset() to reset database-level statistics, or pg_stat_reset_single_table_counters(oid) for a specific table', 'TRUNCATE pg_stat_user_tables', 'DELETE FROM pg_statistics'], correctAnswer: 1, explanation: 'pg_stat_reset() resets all statistics for the current database (counters return to zero). pg_stat_reset_single_table_counters() resets for a specific table. pg_stat_reset_shared() resets cluster-wide shared statistics. This is useful when you want fresh measurements after a configuration change.', codeSnippet: "-- Reset all stats for current database:\nSELECT pg_stat_reset();\n\n-- Reset stats for specific table:\nSELECT pg_stat_reset_single_table_counters('orders'::regclass);\n\n-- Reset shared stats (bgwriter, WAL, etc.):\nSELECT pg_stat_reset_shared('bgwriter');\n\n-- Check when stats were last reset:\nSELECT stats_reset FROM pg_stat_database\nWHERE datname = current_database();", tags: ['admin', 'pg-stat', 'reset', 'monitoring'] },
  { id: 'pg-admin-l2-026', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'What is the pg_restore --create flag?', options: ['Creates the backup file', 'Creates the target database before restoring — includes the CREATE DATABASE statement in the restore, so the database does not need to exist beforehand', 'Creates indexes during restore', 'Creates a restore log file'], correctAnswer: 1, explanation: 'pg_restore --create (-C) first issues a CREATE DATABASE command and then connects to the new database and restores into it. This is useful for restoring to a fresh server. Without --create, you must create the database manually first.', codeSnippet: "# Restore including database creation:\npg_restore --create -d postgres backup.dump\n# Connects to 'postgres' db first,\n# creates the target database,\n# then restores into it\n\n# Without --create (database must exist):\ncreatedb mydb\npg_restore -d mydb backup.dump\n\n# Create with clean (drop if exists):\npg_restore --create --clean -d postgres backup.dump", tags: ['admin', 'backup', 'pg-restore', 'create'] },
  { id: 'pg-admin-l2-027', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What information does VACUUM VERBOSE provide?', options: ['Just the number of dead tuples removed', 'Detailed output per table including pages scanned, dead tuples removed, pages with free space, current versus original table size, and index passes performed', 'Only timing information', 'Verbose SQL execution plan'], correctAnswer: 1, explanation: 'VACUUM VERBOSE outputs detailed per-table statistics: number of pages and tuples examined, dead tuples removed, number of index passes, pages that could be truncated, and the final table size. This is invaluable for understanding vacuum behavior on specific tables.', codeSnippet: "VACUUM VERBOSE orders;\n-- INFO: vacuuming \"public.orders\"\n-- INFO: finished vacuuming \"public.orders\":\n-- index scans: 1\n-- pages: 0 removed, 5432 remain, 12 scanned (0.22% of total)\n-- tuples: 1500 removed, 450000 remain, 0 are dead but not yet removable\n-- removable cutoff: 987654, not yet removable cutoff: 987655\n-- index scan needed: 3 pages from table (0.06%) had 1500 dead tuples\n-- I/O timings: read: 12.34 ms, write: 5.67 ms", tags: ['admin', 'vacuum', 'verbose', 'diagnostics'] },
  { id: 'pg-admin-l2-028', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Tablespaces', question: 'How do you set a default tablespace for new objects in a database?', options: ['ALTER DATABASE mydb SET default_tablespace = \'fast_ssd\';', 'SET TABLESPACE default fast_ssd', 'Only through postgresql.conf', 'DEFAULT TABLESPACE fast_ssd'], correctAnswer: 0, explanation: 'ALTER DATABASE ... SET default_tablespace changes the default tablespace for new objects in that database. You can also SET default_tablespace for the current session. Objects created without an explicit TABLESPACE clause will use this setting.', codeSnippet: "-- Set default for database:\nALTER DATABASE mydb SET default_tablespace = 'fast_ssd';\n\n-- Set default for current session:\nSET default_tablespace = 'fast_ssd';\n\n-- Set default for a specific role:\nALTER ROLE app_user SET default_tablespace = 'fast_ssd';\n\n-- New tables automatically use the default:\nCREATE TABLE new_table (id SERIAL);  -- goes to fast_ssd\n\n-- Override per-table:\nCREATE TABLE slow_table (id SERIAL) TABLESPACE pg_default;", tags: ['admin', 'tablespaces', 'default'] },
  { id: 'pg-admin-l2-029', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What does pg_stat_io show (PostgreSQL 16+)?', options: ['I/O statistics per file', 'Detailed I/O statistics broken down by backend type, I/O context, and I/O object — shows reads, writes, extends, hits, and evictions for shared buffers and other I/O paths', 'I/O wait times only', 'Input/output device status'], correctAnswer: 1, explanation: 'pg_stat_io (PostgreSQL 16+) provides comprehensive I/O statistics broken down by: backend_type (client backend, autovacuum, checkpointer, etc.), io_context (normal, vacuum, bulkread, bulkwrite), and io_object (relation, temp). This replaces the need to piece together I/O info from multiple views.', codeSnippet: "-- I/O statistics by backend type (PG 16+):\nSELECT backend_type, io_object, io_context,\n  reads, read_time, writes, write_time,\n  hits, evictions\nFROM pg_stat_io\nWHERE reads > 0 OR writes > 0\nORDER BY reads + writes DESC;", tags: ['admin', 'pg-stat', 'io', 'monitoring'] },
  { id: 'pg-admin-l2-030', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'ANALYZE', question: 'How do you check the collected statistics for a column?', options: ['DESCRIBE STATISTICS column', 'Query the pg_stats view which shows per-column statistics including null fraction, distinct values, most common values, histogram bounds, and correlation', 'SHOW STATS FOR column', 'Use EXPLAIN to see column stats'], correctAnswer: 1, explanation: 'pg_stats is a human-readable view of pg_statistic. It shows: null_frac (fraction of nulls), n_distinct (estimated distinct values), most_common_vals/most_common_freqs, histogram_bounds, and correlation (physical vs logical ordering correlation). This helps understand planner decisions.', codeSnippet: "-- View statistics for a table's columns:\nSELECT attname, null_frac, n_distinct,\n  most_common_vals, most_common_freqs,\n  correlation\nFROM pg_stats\nWHERE tablename = 'orders'\nORDER BY attname;\n\n-- Check histogram bounds:\nSELECT attname, histogram_bounds\nFROM pg_stats\nWHERE tablename = 'orders'\n  AND attname = 'created_at';", tags: ['admin', 'analyze', 'pg-stats', 'planner'] },
  { id: 'pg-admin-l2-031', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'What does pg_dump --exclude-table do?', options: ['Excludes a table from the dump', 'Dumps only the excluded table', 'Uses -T pattern to exclude tables matching a pattern from the dump — useful for skipping large temporary or log tables', 'Excludes table constraints'], correctAnswer: 2, explanation: 'pg_dump -T (--exclude-table) excludes tables matching the given pattern from the dump. Supports wildcards. Can be specified multiple times. This is useful for excluding large audit/log tables, temp tables, or tables that can be regenerated.', codeSnippet: "# Exclude specific table:\npg_dump -T audit_log mydb > backup.sql\n\n# Exclude multiple tables:\npg_dump -T audit_log -T temp_data mydb > backup.sql\n\n# Exclude by pattern:\npg_dump -T 'tmp_*' -T 'log_*' mydb > backup.sql\n\n# Exclude table data only (keep schema):\npg_dump --exclude-table-data='audit_*' mydb > backup.sql", tags: ['admin', 'backup', 'pg-dump', 'exclude'] },
  { id: 'pg-admin-l2-032', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is table bloat and how does it occur?', options: ['Tables that have too many columns', 'Wasted space in table files caused by dead tuples from UPDATE and DELETE operations — in MVCC, old row versions are not immediately removed, and without timely VACUUM, the table file grows beyond what the live data requires', 'Tables that are too large', 'Tables with too many indexes'], correctAnswer: 1, explanation: 'In PostgreSQL MVCC, UPDATE creates a new tuple and marks the old one as dead. DELETE marks tuples as dead. These dead tuples occupy space until VACUUM reclaims it. If vacuum falls behind (high churn rate, long transactions preventing cleanup), tables bloat — the file grows much larger than the live data needs.', codeSnippet: "-- Estimate table bloat:\nSELECT\n  relname,\n  pg_size_pretty(pg_relation_size(oid)) AS actual_size,\n  pg_size_pretty(\n    (reltuples * avg_tuple_len)::BIGINT\n  ) AS estimated_live_size,\n  n_dead_tup\nFROM pg_class\nJOIN pg_stat_user_tables USING (relname)\nCROSS JOIN LATERAL (\n  SELECT avg(avg_width) AS avg_tuple_len FROM pg_stats\n  WHERE tablename = relname\n) s\nWHERE relkind = 'r'\nORDER BY pg_relation_size(oid) DESC;", tags: ['admin', 'vacuum', 'bloat', 'mvcc'] },
  { id: 'pg-admin-l2-033', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'How do you identify tables that need new indexes?', options: ['PostgreSQL suggests indexes automatically', 'Check pg_stat_user_tables for tables with high sequential scan counts (seq_scan) and many rows read (seq_tup_read) relative to index scans (idx_scan) — these are candidates for indexing', 'Use EXPLAIN on every query', 'Check pg_stat_indexes'], correctAnswer: 1, explanation: 'A table with many sequential scans reading many rows but few or no index scans likely benefits from an index on commonly filtered columns. Combine this with pg_stat_statements to identify the actual queries causing sequential scans.', codeSnippet: "-- Tables with high seq scan to idx scan ratio:\nSELECT relname,\n  seq_scan, seq_tup_read,\n  idx_scan, idx_tup_fetch,\n  n_live_tup,\n  CASE WHEN seq_scan > 0\n    THEN seq_tup_read / seq_scan\n    ELSE 0\n  END AS avg_seq_rows\nFROM pg_stat_user_tables\nWHERE seq_scan > 50\n  AND n_live_tup > 10000\nORDER BY seq_tup_read DESC;", tags: ['admin', 'pg-stat', 'indexes', 'missing-indexes'] },
  { id: 'pg-admin-l2-034', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'How do you verify a pg_dump backup is valid?', options: ['There is no way to verify', 'Restore it to a test database and check — pg_restore -l lists contents without restoring; for full verification, restore to a temporary database and run validation queries', 'Just check the file size', 'Use md5sum on the dump file'], correctAnswer: 1, explanation: 'The most reliable verification is restoring the dump to a test database. pg_restore -l (list mode) can check if the dump structure is readable. For production, implement automated restore testing to a staging environment. Checking file size and checksums detect corruption but not logical issues.', codeSnippet: "# Quick check: list dump contents\npg_restore -l backup.dump > /dev/null && echo 'OK'\n\n# Full verification: restore to test database\ncreatedb test_restore\npg_restore -d test_restore backup.dump\n\n# Validate data:\npsql -d test_restore -c \"\n  SELECT schemaname, tablename, n_live_tup\n  FROM pg_stat_user_tables\n  ORDER BY n_live_tup DESC;\"\n\n# Cleanup:\ndropdb test_restore", tags: ['admin', 'backup', 'verification', 'testing'] },
  { id: 'pg-admin-l2-035', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is the free space map (FSM)?', options: ['A map of available disk space', 'A per-table data structure that tracks free space on each page — VACUUM updates the FSM so future INSERTs can find pages with available space without scanning the entire table', 'A map of free memory', 'A map of deleted files'], correctAnswer: 1, explanation: 'The free space map tracks how much free space is available on each heap page. When inserting a new row, PostgreSQL consults the FSM to find a page with enough space. VACUUM updates the FSM by recording reclaimed space. Without accurate FSM data, inserts always extend the table instead of reusing space.', codeSnippet: "-- Check FSM data using pg_freespace extension:\nCREATE EXTENSION pg_freespace;\n\n-- Free space per page:\nSELECT blkno, avail\nFROM pg_freespace('orders')\nWHERE avail > 0\nLIMIT 20;\n\n-- Average free space:\nSELECT avg(avail) AS avg_free_bytes,\n  count(*) AS total_pages\nFROM pg_freespace('orders');", tags: ['admin', 'vacuum', 'free-space-map', 'storage'] },
  { id: 'pg-admin-l2-036', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Tablespaces', question: 'Can indexes be placed in a different tablespace from their table?', options: ['No, they must be in the same tablespace', 'Yes — you can specify TABLESPACE when creating an index to place it on different storage than the table, enabling I/O distribution', 'Only partial indexes', 'Only with GiST indexes'], correctAnswer: 1, explanation: 'Indexes can reside in a different tablespace from their table. This is a common I/O optimization: place the table on one disk and its indexes on another to parallelize sequential and random I/O. This is particularly effective with spinning disks.', codeSnippet: "-- Table on SSD, index on separate NVMe:\nCREATE TABLE orders (\n  id SERIAL PRIMARY KEY, data JSONB\n) TABLESPACE data_ssd;\n\nCREATE INDEX idx_orders_data ON orders\n  USING gin (data)\n  TABLESPACE index_nvme;\n\n-- Move existing index:\nALTER INDEX idx_orders_data SET TABLESPACE index_nvme;\n\n-- Check locations:\nSELECT tablename, tablespace FROM pg_tables WHERE tablename = 'orders';\nSELECT indexname, tablespace FROM pg_indexes WHERE tablename = 'orders';", tags: ['admin', 'tablespaces', 'indexes', 'io-optimization'] },
  { id: 'pg-admin-l2-037', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What is the pg_stat_statements extension?', options: ['A built-in view for statement statistics', 'An extension that tracks execution statistics of all SQL statements — including call count, total/mean/min/max time, rows returned, and shared buffer hits/reads per normalized query', 'A statement logging tool', 'A query rewrite optimizer'], correctAnswer: 1, explanation: 'pg_stat_statements is a must-have extension for query performance analysis. It groups queries by their normalized form (replacing literal values with parameters) and tracks: calls, total_exec_time, rows, shared_blks_hit/read, temp_blks, and WAL usage. Essential for identifying slow and frequent queries.', codeSnippet: "-- Install:\nCREATE EXTENSION pg_stat_statements;\n-- Requires: shared_preload_libraries = 'pg_stat_statements'\n\n-- Top queries by total time:\nSELECT query, calls,\n  round(total_exec_time::numeric, 2) AS total_ms,\n  round(mean_exec_time::numeric, 2) AS mean_ms,\n  rows\nFROM pg_stat_statements\nORDER BY total_exec_time DESC\nLIMIT 10;\n\n-- Reset statistics:\nSELECT pg_stat_statements_reset();", tags: ['admin', 'pg-stat', 'pg-stat-statements', 'performance'] },
  { id: 'pg-admin-l2-038', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What does VACUUM FREEZE do?', options: ['Freezes the database', 'Aggressively freezes all eligible tuples regardless of their age — marks them as visible to all transactions, preventing transaction ID wraparound; useful before large data loads or to reset freeze counters', 'Stops vacuum from running', 'Pauses all writes during vacuum'], correctAnswer: 1, explanation: 'VACUUM FREEZE sets vacuum_freeze_min_age to 0, causing all unfrozen tuples to be frozen immediately. This is useful for static tables that will not be modified, as it prevents future anti-wraparound vacuum from needing to scan the table. Also useful before long-term archival.', codeSnippet: "-- Freeze a static lookup table:\nVACUUM FREEZE lookup_codes;\n\n-- Verify freezing:\nSELECT relname, age(relfrozenxid) AS xid_age\nFROM pg_class\nWHERE relname = 'lookup_codes';\n-- xid_age should be very small (recently frozen)\n\n-- Compare with related setting:\nSHOW vacuum_freeze_min_age;     -- 50000000\nSHOW vacuum_freeze_table_age;   -- 150000000\nSHOW autovacuum_freeze_max_age; -- 200000000", tags: ['admin', 'vacuum', 'freeze', 'wraparound'] },
  { id: 'pg-admin-l2-039', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'What is --no-owner flag in pg_dump/pg_restore?', options: ['Removes the dump file owner', 'Omits SET OWNER commands from the dump — allows restoring to a database with different role names without ownership errors', 'Prevents anyone from owning the backup', 'Creates objects without an owner'], correctAnswer: 1, explanation: '--no-owner omits ALTER OWNER commands from the dump/restore. This is useful when restoring to a different environment where the original owner roles may not exist. All objects will be owned by the role running the restore.', codeSnippet: "# Dump without ownership info:\npg_dump --no-owner mydb > backup.sql\n\n# Restore without setting ownership:\npg_restore --no-owner -d mydb backup.dump\n\n# Also useful: --no-privileges (skip GRANT/REVOKE)\npg_dump --no-owner --no-privileges mydb > portable_backup.sql", tags: ['admin', 'backup', 'pg-dump', 'no-owner'] },
  { id: 'pg-admin-l2-040', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'ANALYZE', question: 'What is the difference between regular ANALYZE and autovacuum-triggered ANALYZE?', options: ['They collect different statistics', 'They are identical in what they do — both sample table data and update pg_statistic; the difference is that autovacuum-triggered ANALYZE runs automatically when modification thresholds are exceeded, while manual ANALYZE runs on demand', 'Autovacuum ANALYZE is faster', 'Manual ANALYZE collects more data'], correctAnswer: 1, explanation: 'Both manual and auto-triggered ANALYZE perform the same sampling and statistics computation. The difference is timing: autovacuum checks periodically (autovacuum_naptime) and triggers ANALYZE based on change thresholds. Manual ANALYZE runs immediately. Use manual ANALYZE after bulk data loads or schema changes.', codeSnippet: "-- Manual ANALYZE after bulk load:\nCOPY large_table FROM '/data/import.csv' CSV;\nANALYZE large_table;  -- immediate statistics update\n\n-- Check auto vs manual analyze history:\nSELECT relname,\n  last_analyze,\n  last_autoanalyze,\n  analyze_count,\n  autoanalyze_count\nFROM pg_stat_user_tables\nORDER BY relname;", tags: ['admin', 'analyze', 'autovacuum', 'comparison'] },
  { id: 'pg-admin-l2-041', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'How do you monitor lock contention using system views?', options: ['Use SHOW LOCKS', 'Query pg_locks joined with pg_stat_activity to see which sessions hold or wait for locks, and what queries they are running', 'Use pg_stat_locks', 'Use EXPLAIN to see locks'], correctAnswer: 1, explanation: 'pg_locks shows all current locks with their type, mode, and whether they are granted. Joining with pg_stat_activity adds query and session context. Filter for granted = false to find blocked sessions. This is essential for diagnosing deadlocks and lock contention.', codeSnippet: "-- Find blocked queries and what's blocking them:\nSELECT\n  blocked.pid AS blocked_pid,\n  blocked.query AS blocked_query,\n  blocking.pid AS blocking_pid,\n  blocking.query AS blocking_query\nFROM pg_locks bl\nJOIN pg_stat_activity blocked ON bl.pid = blocked.pid\nJOIN pg_locks kl ON bl.locktype = kl.locktype\n  AND bl.relation = kl.relation\n  AND bl.pid != kl.pid\nJOIN pg_stat_activity blocking ON kl.pid = blocking.pid\nWHERE NOT bl.granted;", tags: ['admin', 'pg-stat', 'locks', 'contention'] },
  { id: 'pg-admin-l2-042', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Tablespaces', question: 'What happens to a tablespace directory when you DROP TABLESPACE?', options: ['The directory is deleted automatically', 'The tablespace can only be dropped if it is empty (no objects); the directory and its symbolic link in pg_tblspc are then removed by PostgreSQL', 'All data is moved to pg_default first', 'Nothing happens to the directory'], correctAnswer: 1, explanation: 'DROP TABLESPACE fails if any objects still reside in it. You must first move all objects to another tablespace or drop them. Once the tablespace is empty, DROP TABLESPACE removes the directory and the symbolic link in the pg_tblspc directory.', codeSnippet: "-- Check what's in a tablespace:\nSELECT c.relname, c.relkind,\n  ts.spcname AS tablespace\nFROM pg_class c\nJOIN pg_tablespace ts ON c.reltablespace = ts.oid\nWHERE ts.spcname = 'old_space';\n\n-- Move objects out:\nALTER TABLE my_table SET TABLESPACE pg_default;\nALTER INDEX my_index SET TABLESPACE pg_default;\n\n-- Now drop:\nDROP TABLESPACE old_space;", tags: ['admin', 'tablespaces', 'drop'] },
  { id: 'pg-admin-l2-043', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is the DISABLE_PAGE_SKIPPING option for VACUUM?', options: ['Disables vacuum entirely', 'Forces VACUUM to process all pages including those marked as all-visible in the visibility map — useful when the visibility map may be corrupted or for thorough cleanup', 'Skips page headers', 'Disables TOAST page cleaning'], correctAnswer: 1, explanation: 'VACUUM normally skips pages marked as all-visible in the visibility map. VACUUM (DISABLE_PAGE_SKIPPING) forces it to examine every page. This is useful for recovering from visibility map corruption or when you want the most thorough cleanup possible (at the cost of being much slower).', codeSnippet: "-- Normal vacuum (skips all-visible pages):\nVACUUM orders;\n\n-- Force scan of all pages:\nVACUUM (DISABLE_PAGE_SKIPPING) orders;\n\n-- Combined with verbose and analyze:\nVACUUM (VERBOSE, ANALYZE, DISABLE_PAGE_SKIPPING) orders;\n\n-- Use after suspected data corruption or\n-- after modifying rows via direct file manipulation", tags: ['admin', 'vacuum', 'page-skipping', 'thorough'] },
  { id: 'pg-admin-l2-044', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'What is the --section flag in pg_dump?', options: ['Dumps a specific section of a table', 'Allows dumping specific sections of the database: pre-data (types, functions, schemas), data (table contents), or post-data (indexes, triggers, constraints)', 'Sections the output into multiple files', 'Marks sections in the dump for easy reading'], correctAnswer: 1, explanation: 'pg_dump --section allows selective dumping of: pre-data (CREATE TABLE, types, functions), data (COPY/INSERT statements), or post-data (indexes, constraints, triggers). This is useful for parallel restore strategies: restore pre-data, load data in parallel, then restore post-data.', codeSnippet: "# Dump only schema definitions:\npg_dump --section=pre-data mydb > schema.sql\n\n# Dump only data:\npg_dump --section=data mydb > data.sql\n\n# Dump only indexes and constraints:\npg_dump --section=post-data mydb > post_data.sql\n\n# Fast restore strategy:\npsql mydb < schema.sql      # 1. Create tables\n# Load data in parallel...    # 2. COPY data\npsql mydb < post_data.sql    # 3. Create indexes", tags: ['admin', 'backup', 'pg-dump', 'sections'] },
  { id: 'pg-admin-l2-045', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'ANALYZE', question: 'What does the n_distinct statistic mean in pg_stats?', options: ['The number of NOT NULL values', 'Estimated number of distinct values — positive numbers are absolute counts, negative numbers represent the fraction of total rows (e.g., -1 means all values are unique, -0.5 means about half are unique)', 'The number of distinct data types', 'The number of distinct indexes'], correctAnswer: 1, explanation: 'In pg_stats, n_distinct > 0 means the exact estimated count of distinct values. n_distinct < 0 means |n_distinct| is the ratio of distinct values to total rows. -1 means all values are unique (like a primary key). -0.1 means about 10% of rows have unique values. The planner uses this for selectivity estimates.', codeSnippet: "SELECT attname, n_distinct\nFROM pg_stats\nWHERE tablename = 'orders';\n\n-- id:          -1      (all unique = PK)\n-- status:      5       (5 distinct values)\n-- customer_id: -0.1    (10% of rows are unique)\n-- created_at:  -0.98   (98% of rows have unique timestamps)\n\n-- Override if estimate is wrong:\nALTER TABLE orders ALTER COLUMN status\n  SET (n_distinct = 5);", tags: ['admin', 'analyze', 'n-distinct', 'statistics'] },
  { id: 'pg-admin-l2-046', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What does pg_statio_user_tables show?', options: ['Standard I/O statistics', 'Per-table I/O statistics showing heap blocks read from disk versus cache, and index blocks read from disk versus cache — used to calculate cache hit ratios per table', 'Storage allocation per table', 'Table I/O wait times'], correctAnswer: 1, explanation: 'pg_statio_user_tables shows heap_blks_read/hit, idx_blks_read/hit, toast_blks_read/hit, and tidx_blks_read/hit per table. The ratio hit/(hit+read) gives the cache hit rate. Tables with low hit rates may need more shared_buffers or have inefficient access patterns.', codeSnippet: "-- Per-table cache hit ratio:\nSELECT relname,\n  heap_blks_hit, heap_blks_read,\n  CASE WHEN heap_blks_hit + heap_blks_read > 0\n    THEN round(100.0 * heap_blks_hit /\n      (heap_blks_hit + heap_blks_read), 2)\n    ELSE 100\n  END AS heap_cache_hit_pct,\n  idx_blks_hit, idx_blks_read\nFROM pg_statio_user_tables\nWHERE heap_blks_read > 0\nORDER BY heap_blks_read DESC;", tags: ['admin', 'pg-stat', 'io', 'cache-hit-ratio'] },
  { id: 'pg-admin-l2-047', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'How does VACUUM interact with concurrent transactions?', options: ['VACUUM blocks all transactions', 'VACUUM can only remove dead tuples that are no longer visible to any active transaction — long-running transactions prevent VACUUM from cleaning up tuples they might still need to see', 'VACUUM runs after all transactions complete', 'VACUUM is unaffected by other transactions'], correctAnswer: 1, explanation: 'VACUUM cannot remove tuples that any active transaction might still need (based on the oldest active transaction ID, or xmin horizon). Long-running transactions, idle-in-transaction sessions, and stale replication slots can all hold back the xmin horizon, preventing vacuum from reclaiming space.', codeSnippet: "-- Check what's holding back vacuum:\nSELECT pid, xact_start, state, query\nFROM pg_stat_activity\nWHERE backend_xmin IS NOT NULL\nORDER BY age(backend_xmin) DESC;\n\n-- Check replication slot lag:\nSELECT slot_name, age(xmin) AS slot_xmin_age,\n  age(catalog_xmin) AS catalog_xmin_age\nFROM pg_replication_slots;\n\n-- Set idle-in-transaction timeout to prevent holding xmin:\nSET idle_in_transaction_session_timeout = '5min';", tags: ['admin', 'vacuum', 'transactions', 'xmin-horizon'] },
  { id: 'pg-admin-l2-048', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'What is pg_dump --exclude-table-data used for?', options: ['Excludes the table entirely', 'Dumps the table structure (DDL) but excludes the data for tables matching the pattern — useful for large tables whose data can be regenerated or is not needed in the backup', 'Excludes data type definitions', 'Excludes table metadata'], correctAnswer: 1, explanation: '--exclude-table-data keeps the CREATE TABLE statement in the dump but omits the COPY/INSERT data. This is useful for large log or staging tables where you want the schema preserved for a clean restore but do not need the actual data.', codeSnippet: "# Dump everything but exclude data for log tables:\npg_dump --exclude-table-data='audit_*' \\\n  --exclude-table-data='log_*' \\\n  mydb > backup.sql\n\n# The dump will contain:\n# CREATE TABLE audit_events (...)  -- schema preserved\n# -- No COPY audit_events           -- data excluded\n# COPY orders FROM stdin;            -- other data included", tags: ['admin', 'backup', 'pg-dump', 'exclude-data'] },
  { id: 'pg-admin-l2-049', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What does pg_stat_progress_vacuum show?', options: ['Vacuum scheduling information', 'Real-time progress of currently running VACUUM operations — shows which phase the vacuum is in, how many pages have been processed, and how many dead tuples have been found', 'Historical vacuum statistics', 'Vacuum configuration'], correctAnswer: 1, explanation: 'pg_stat_progress_vacuum (PostgreSQL 9.6+) shows running vacuum operations with: phase (scanning heap, vacuuming indexes, etc.), heap_blks_total, heap_blks_scanned, heap_blks_vacuumed, num_dead_tuples, and index_vacuum_count. This lets you estimate completion time for long-running vacuums.', codeSnippet: "-- Monitor running vacuum operations:\nSELECT pid, datname, relid::regclass AS table_name,\n  phase,\n  heap_blks_total, heap_blks_scanned, heap_blks_vacuumed,\n  index_vacuum_count, num_dead_tuples\nFROM pg_stat_progress_vacuum;\n\n-- Phases:\n-- 'initializing'\n-- 'scanning heap'\n-- 'vacuuming indexes'\n-- 'vacuuming heap'\n-- 'cleaning up indexes'\n-- 'truncating heap'\n-- 'performing final cleanup'", tags: ['admin', 'pg-stat', 'vacuum', 'progress'] },
  { id: 'pg-admin-l2-050', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is the PARALLEL option for VACUUM (PostgreSQL 13+)?', options: ['Vacuums multiple tables at once', 'Specifies the number of parallel workers for index vacuuming — allows vacuuming multiple indexes on the same table simultaneously', 'Runs vacuum in a separate process', 'Enables autovacuum parallelism'], correctAnswer: 1, explanation: 'VACUUM (PARALLEL n) allows parallel index vacuuming within a single VACUUM operation. Each worker processes a different index simultaneously. The heap itself is still processed by a single worker. This is particularly beneficial for tables with many or large indexes.', codeSnippet: "-- Parallel vacuum with 4 index workers:\nVACUUM (PARALLEL 4) orders;\n\n-- Default: uses min(nindexes, autovacuum_max_workers) workers\nVACUUM orders;  -- auto-parallelism\n\n-- Disable parallel vacuum:\nVACUUM (PARALLEL 0) orders;\n\n-- Note: only index vacuuming is parallelized\n-- Heap scanning and truncation are single-threaded", tags: ['admin', 'vacuum', 'parallel', 'indexes'] },
  { id: 'pg-admin-l2-051', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Tablespaces', question: 'How do tablespaces work with pg_dump and pg_restore?', options: ['Tablespace assignments are always preserved', 'pg_dump records tablespace assignments in the dump; pg_restore --no-tablespaces option can be used to ignore them and place everything in the default tablespace during restore', 'Tablespace info is never included in dumps', 'Tablespaces must be manually recreated'], correctAnswer: 1, explanation: 'pg_dump includes SET TABLESPACE commands in the output. When restoring to a different server that may not have the same tablespaces, use pg_restore --no-tablespaces to skip tablespace assignments. Objects will be created in the default tablespace. The tablespaces themselves are cluster-wide and not included in per-database dumps.', codeSnippet: "# Dump includes tablespace info by default:\npg_dump mydb > backup.sql\n# Contains: SET default_tablespace = 'fast_ssd';\n\n# Restore ignoring tablespace assignments:\npg_restore --no-tablespaces -d mydb backup.dump\n\n# Or with plain SQL:\npsql mydb < backup.sql\n# Will fail if tablespace doesn't exist\n# unless you sed out the SET default_tablespace lines", tags: ['admin', 'tablespaces', 'pg-dump', 'restore'] },
  { id: 'pg-admin-l2-052', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'ANALYZE', question: 'How does ANALYZE sample data from large tables?', options: ['It reads every row', 'ANALYZE takes a random sample of pages (based on default_statistics_target * 300) and reads all tuples on those pages — this provides accurate statistics without scanning the entire table', 'It only reads the first 1000 rows', 'It uses index entries only'], correctAnswer: 1, explanation: 'ANALYZE samples approximately 300 * statistics_target random pages from the table. It reads all tuples on those pages. For a default statistics_target of 100, this means ~30,000 pages are sampled. This provides statistically accurate estimates while being fast even for very large tables.', codeSnippet: "-- Default sample size:\n-- 300 * default_statistics_target = 300 * 100 = 30,000 pages\n\n-- For a specific column with higher target:\nALTER TABLE large_table ALTER COLUMN skewed_col\n  SET STATISTICS 1000;\n-- Will sample: 300 * 1000 = 300,000 pages\n\nANALYZE VERBOSE large_table;\n-- Shows: ... scanned 30000 of 500000 pages ...", tags: ['admin', 'analyze', 'sampling', 'statistics'] },
  { id: 'pg-admin-l2-053', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What does pg_stat_wal (PostgreSQL 14+) show?', options: ['WAL file locations', 'WAL generation statistics including total WAL records, bytes generated, full-page images written, buffers written, and sync times — useful for understanding write amplification and WAL pressure', 'WAL replication status', 'WAL archive status'], correctAnswer: 1, explanation: 'pg_stat_wal provides cumulative statistics about WAL generation: wal_records, wal_fpi (full page images), wal_bytes, wal_buffers_full, wal_write/sync counts and times. High wal_fpi indicates potential for full_page_writes tuning. High wal_buffers_full suggests increasing wal_buffers.', codeSnippet: "-- WAL generation statistics (PG 14+):\nSELECT\n  wal_records, wal_fpi,\n  pg_size_pretty(wal_bytes) AS wal_generated,\n  wal_buffers_full,\n  wal_write, wal_sync,\n  round(wal_write_time::numeric, 2) AS write_time_ms,\n  round(wal_sync_time::numeric, 2) AS sync_time_ms\nFROM pg_stat_wal;", tags: ['admin', 'pg-stat', 'wal', 'monitoring'] },
  { id: 'pg-admin-l2-054', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'What is the difference between logical and physical backups?', options: ['Physical backups are on paper', 'Logical backups (pg_dump) export SQL/data that is database-version portable; physical backups (pg_basebackup) copy raw data files and support point-in-time recovery but require the same PG major version', 'Logical backups are faster', 'Physical backups are smaller'], correctAnswer: 1, explanation: 'Logical backups (pg_dump) produce SQL or archive format, are version-portable (can restore to different major versions), and support selective restore. Physical backups (pg_basebackup + WAL archiving) copy raw data files, are faster for large databases, support PITR, but require the same major version for restore.', codeSnippet: "# Logical backup (pg_dump):\npg_dump -Fc mydb > logical_backup.dump\n# Pros: version-portable, selective, readable\n# Cons: slower for large DBs, no PITR\n\n# Physical backup (pg_basebackup):\npg_basebackup -D /backup/base -Fp -Xs -P\n# Pros: fast, supports PITR, includes everything\n# Cons: same PG version required, all-or-nothing", tags: ['admin', 'backup', 'logical', 'physical', 'comparison'] },
  { id: 'pg-admin-l2-055', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is HOT (Heap-Only Tuple) and how does it reduce vacuum work?', options: ['A temperature monitoring feature', 'HOT updates place the new tuple version on the same page as the old one without updating indexes — the old tuple has a redirect pointer, reducing both index maintenance and vacuum work', 'A caching mechanism', 'A replication feature'], correctAnswer: 1, explanation: 'When an UPDATE does not change any indexed columns and there is free space on the same page (controlled by fillfactor), PostgreSQL can perform a HOT update. The old tuple points to the new one on the same page. No index entries are modified. Dead HOT tuples can be pruned during regular page access without a full VACUUM.', codeSnippet: "-- Enable HOT updates by leaving free space:\nCREATE TABLE accounts (\n  id SERIAL PRIMARY KEY,\n  balance NUMERIC, updated_at TIMESTAMPTZ\n) WITH (fillfactor = 70);\n\n-- Check HOT update ratio:\nSELECT relname,\n  n_tup_upd AS updates,\n  n_tup_hot_upd AS hot_updates,\n  CASE WHEN n_tup_upd > 0\n    THEN round(100.0 * n_tup_hot_upd / n_tup_upd, 1)\n    ELSE 0\n  END AS hot_pct\nFROM pg_stat_user_tables\nWHERE n_tup_upd > 0\nORDER BY n_tup_upd DESC;", tags: ['admin', 'vacuum', 'hot-updates', 'fillfactor'] },
  { id: 'pg-admin-l2-056', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Tablespaces', question: 'How do you check the disk space used by each tablespace?', options: ['df -h', 'Use pg_tablespace_size() function to get the total size of all objects in each tablespace', 'SHOW TABLESPACE SIZES', 'Check the file system manually'], correctAnswer: 1, explanation: 'pg_tablespace_size() returns the total disk space used by all objects in a tablespace. Wrap with pg_size_pretty() for human-readable output. \\db+ in psql also shows tablespace sizes.', codeSnippet: "-- Size of each tablespace:\nSELECT spcname,\n  pg_size_pretty(pg_tablespace_size(spcname)) AS size,\n  pg_tablespace_location(oid) AS location\nFROM pg_tablespace\nORDER BY pg_tablespace_size(spcname) DESC;\n\n-- In psql:\n\\db+", tags: ['admin', 'tablespaces', 'disk-space', 'monitoring'] },
  { id: 'pg-admin-l2-057', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'How do you identify the most time-consuming queries?', options: ['Check postgresql.log only', 'Use pg_stat_statements extension and sort by total_exec_time to find queries consuming the most total server time — also check mean_exec_time for individually slow queries', 'Use EXPLAIN on every query', 'Use pg_stat_activity only'], correctAnswer: 1, explanation: 'pg_stat_statements tracks execution statistics per normalized query. Sort by total_exec_time to find queries consuming the most total CPU time (high calls * mean time). Sort by mean_exec_time to find individually slow queries. Sort by shared_blks_read for I/O-heavy queries.', codeSnippet: "-- Top queries by total time:\nSELECT query, calls,\n  total_exec_time / 1000 AS total_sec,\n  mean_exec_time AS avg_ms,\n  rows / calls AS avg_rows\nFROM pg_stat_statements\nORDER BY total_exec_time DESC\nLIMIT 10;\n\n-- Top queries by I/O:\nSELECT query, calls,\n  shared_blks_read, shared_blks_hit,\n  temp_blks_read, temp_blks_written\nFROM pg_stat_statements\nORDER BY shared_blks_read DESC\nLIMIT 10;", tags: ['admin', 'pg-stat', 'performance', 'slow-queries'] },
  { id: 'pg-admin-l2-058', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is the INDEX_CLEANUP option for VACUUM?', options: ['Removes unused indexes', 'Controls whether VACUUM performs index cleanup — INDEX_CLEANUP OFF skips index vacuuming, making VACUUM much faster but leaving dead index entries; useful in emergencies', 'Reorganizes index pages', 'Only cleans expression indexes'], correctAnswer: 1, explanation: 'VACUUM (INDEX_CLEANUP OFF) skips the index vacuuming phase, which is often the slowest part. This is useful in emergencies (e.g., when approaching transaction ID wraparound) where you need the heap vacuumed quickly. Dead index entries remain but are cleaned up by the next normal vacuum.', codeSnippet: "-- Emergency vacuum: skip index cleanup\nVACUUM (INDEX_CLEANUP OFF, VERBOSE) critical_table;\n\n-- Much faster but leaves dead index entries\n-- Follow up with a normal vacuum when possible:\nVACUUM critical_table;\n\n-- PostgreSQL 14+: automatic INDEX_CLEANUP decision\n-- based on number of dead tuples vs table size", tags: ['admin', 'vacuum', 'index-cleanup', 'emergency'] },
  { id: 'pg-admin-l2-059', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'How do you schedule regular backups in PostgreSQL?', options: ['PostgreSQL has built-in backup scheduling', 'Use OS-level scheduling tools (cron on Linux, Task Scheduler on Windows) to run pg_dump commands at regular intervals — or use backup management tools like pgBackRest or Barman', 'Use pg_cron extension', 'Use pg_agent'], correctAnswer: 1, explanation: 'PostgreSQL does not have built-in backup scheduling. The most common approach is cron jobs running pg_dump or pgBackRest. pgBackRest and Barman are dedicated backup management tools that handle scheduling, retention, verification, and both full and incremental backups. pg_cron can also schedule from within PostgreSQL.', codeSnippet: "# Cron job for daily backup at 2 AM:\n# crontab -e\n0 2 * * * pg_dump -Fc -f /backups/mydb_$(date +\\%Y\\%m\\%d).dump mydb\n\n# With retention (keep 7 days):\n0 2 * * * pg_dump -Fc mydb > /backups/mydb_$(date +\\%Y\\%m\\%d).dump && find /backups -name 'mydb_*.dump' -mtime +7 -delete\n\n# Using pgBackRest (recommended for production):\n# pgbackrest --stanza=mydb --type=full backup\n# pgbackrest --stanza=mydb --type=incr backup", tags: ['admin', 'backup', 'scheduling', 'cron'] },
  { id: 'pg-admin-l2-060', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'ANALYZE', question: 'What happens if statistics are stale or missing?', options: ['Queries fail with errors', 'The query planner may choose suboptimal execution plans — wrong join orders, missing index usage, bad row estimates leading to nested loops where hash joins would be better', 'Statistics are never stale in PostgreSQL', 'The database automatically updates them before each query'], correctAnswer: 1, explanation: 'Stale statistics lead the planner to make wrong assumptions about table sizes, selectivity, and value distribution. This can cause: sequential scans instead of index scans, wrong join orders, inappropriate join methods (nested loop vs hash join), and incorrect parallel worker counts. ANALYZE updates statistics to fix this.', codeSnippet: "-- Signs of stale statistics:\nEXPLAIN ANALYZE SELECT * FROM orders WHERE status = 'pending';\n-- If: Estimated rows=1000 but Actual rows=500000\n-- Then statistics are stale!\n\n-- Fix:\nANALYZE orders;\n\n-- Check staleness:\nSELECT relname,\n  n_mod_since_analyze,\n  last_analyze, last_autoanalyze\nFROM pg_stat_user_tables\nWHERE n_mod_since_analyze > 10000;", tags: ['admin', 'analyze', 'stale-statistics', 'query-planning'] },
  { id: 'pg-admin-l2-061', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What is pg_stat_replication used for?', options: ['Monitoring data replication to external systems', 'Shows the status of WAL sender processes connected to standby servers — including replication state, sent/write/flush/replay LSN positions, and replication lag', 'Managing replication configuration', 'Setting up new replicas'], correctAnswer: 1, explanation: 'pg_stat_replication shows one row per WAL sender on the primary server. It includes: application_name, client_addr, state (streaming/catchup), sent_lsn, write_lsn, flush_lsn, replay_lsn, and the calculated lag. Essential for monitoring replication health and lag.', codeSnippet: "-- On primary: check replication status\nSELECT client_addr, state, sync_state,\n  sent_lsn, write_lsn, flush_lsn, replay_lsn,\n  pg_wal_lsn_diff(sent_lsn, replay_lsn) AS replay_lag_bytes,\n  reply_time\nFROM pg_stat_replication;", tags: ['admin', 'pg-stat', 'replication', 'monitoring'] },
  { id: 'pg-admin-l2-062', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is the TRUNCATE option for VACUUM?', options: ['Truncates the table data', 'Controls whether VACUUM attempts to truncate empty pages at the end of the table to return disk space to the OS — TRUNCATE ON (default) can cause brief locks', 'Truncates long text values', 'Truncates the vacuum log'], correctAnswer: 1, explanation: 'When dead tuples at the end of a table are cleaned up, VACUUM can truncate those trailing empty pages, actually shrinking the file size. This requires a brief ACCESS EXCLUSIVE lock. VACUUM (TRUNCATE OFF) disables this to avoid even brief blocking. Per-table: ALTER TABLE ... SET (vacuum_truncate = off).', codeSnippet: "-- Default: truncate trailing empty pages\nVACUUM orders;\n\n-- Disable truncation (avoid lock):\nVACUUM (TRUNCATE OFF) orders;\n\n-- Per-table setting:\nALTER TABLE orders SET (vacuum_truncate = off);\n\n-- Check setting:\nSELECT reloptions FROM pg_class\nWHERE relname = 'orders';", tags: ['admin', 'vacuum', 'truncate', 'disk-space'] },
  { id: 'pg-admin-l2-063', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'What does pg_dump --jobs (-j) require?', options: ['Multiple CPU cores', 'Directory format (-Fd) — parallel dump with -j only works with directory format because it creates separate files per table that workers can write to simultaneously', 'Custom format (-Fc)', 'A separate backup server'], correctAnswer: 1, explanation: 'Parallel dump (-j) requires directory format (-Fd) because each worker needs to write to a separate file. Custom format produces a single file that cannot be written by multiple workers simultaneously. Parallel restore works with both custom and directory formats.', codeSnippet: "# Parallel DUMP requires directory format:\npg_dump -Fd -j 4 mydb -f backup_dir/\n\n# This does NOT work:\n# pg_dump -Fc -j 4 mydb > backup.dump  -- ERROR\n\n# Parallel RESTORE works with both formats:\npg_restore -j 4 -d mydb backup_dir/    # directory: OK\npg_restore -j 4 -d mydb backup.dump    # custom: OK", tags: ['admin', 'backup', 'parallel', 'directory-format'] },
  { id: 'pg-admin-l2-064', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What is pg_stat_progress_create_index?', options: ['Shows index creation progress', 'Shows real-time progress of CREATE INDEX and REINDEX operations — including the current phase, blocks scanned, tuples processed, and partitions completed', 'Lists indexes being planned', 'Shows index maintenance schedule'], correctAnswer: 1, explanation: 'pg_stat_progress_create_index (PostgreSQL 12+) shows running index creation operations with: phase (initializing, building index, validating, waiting for lockers), blocks_total/done, tuples_total/done, and partitions_total/done. Essential for monitoring long-running CREATE INDEX CONCURRENTLY operations.', codeSnippet: "-- Monitor index creation progress:\nSELECT pid, datname,\n  relid::regclass AS table_name,\n  index_relid::regclass AS index_name,\n  phase,\n  blocks_total, blocks_done,\n  tuples_total, tuples_done,\n  partitions_total, partitions_done\nFROM pg_stat_progress_create_index;\n\n-- Phases for CREATE INDEX CONCURRENTLY:\n-- 'initializing'\n-- 'waiting for writers before build'\n-- 'building index: scanning table'\n-- 'building index: sorting live tuples'\n-- 'building index: loading tuples in tree'\n-- 'waiting for writers before validation'\n-- 'index validation: scanning index'\n-- 'waiting for old snapshots'", tags: ['admin', 'pg-stat', 'create-index', 'progress'] },
  { id: 'pg-admin-l2-065', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'How do you configure autovacuum settings per table?', options: ['Only global settings are available', 'Use ALTER TABLE ... SET (autovacuum_setting = value) to override global settings for specific tables — essential for tables with unusual update patterns', 'Create a per-table vacuum config file', 'Use CREATE VACUUM POLICY'], correctAnswer: 1, explanation: 'Per-table storage parameters override global autovacuum settings. This is critical for: high-churn tables (lower scale_factor for more frequent vacuum), static tables (higher thresholds to avoid unnecessary work), and critical tables (zero cost_delay for aggressive vacuum).', codeSnippet: "-- High-churn table: vacuum more aggressively\nALTER TABLE events SET (\n  autovacuum_vacuum_scale_factor = 0.01,  -- 1% vs default 20%\n  autovacuum_vacuum_threshold = 100,\n  autovacuum_analyze_scale_factor = 0.005,\n  autovacuum_vacuum_cost_delay = 0         -- no throttling\n);\n\n-- Static table: vacuum less frequently\nALTER TABLE lookup_codes SET (\n  autovacuum_vacuum_scale_factor = 0.5,\n  autovacuum_enabled = true\n);\n\n-- Check per-table settings:\nSELECT relname, reloptions\nFROM pg_class WHERE reloptions IS NOT NULL;", tags: ['admin', 'autovacuum', 'per-table', 'tuning'] },
  { id: 'pg-admin-l2-066', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Tablespaces', question: 'What are the permissions required to create a tablespace?', options: ['Any user can create tablespaces', 'Only superusers can create tablespaces because it involves specifying a file system directory — the directory must exist and be owned by the PostgreSQL OS user', 'Database owners can create tablespaces', 'Users with CREATEDB can create tablespaces'], correctAnswer: 1, explanation: 'CREATE TABLESPACE requires superuser privilege because it maps a PostgreSQL abstraction to a physical file system path, which has security implications. The specified directory must exist, be empty, and be owned by the OS user running PostgreSQL (usually postgres).', codeSnippet: "-- Only superuser can create tablespace:\nCREATE TABLESPACE data_ssd LOCATION '/mnt/ssd/pgdata';\n\n-- Prerequisites:\n-- mkdir /mnt/ssd/pgdata\n-- chown postgres:postgres /mnt/ssd/pgdata\n\n-- Grant usage to other roles:\nGRANT CREATE ON TABLESPACE data_ssd TO app_admin;\n\n-- app_admin can now create tables in the tablespace:\nCREATE TABLE my_table (...) TABLESPACE data_ssd;", tags: ['admin', 'tablespaces', 'permissions', 'superuser'] },
  { id: 'pg-admin-l2-067', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'ANALYZE', question: 'What is the correlation statistic in pg_stats?', options: ['Correlation between queries', 'The statistical correlation between the physical row order and the logical order of column values — a value near 1 or -1 indicates good physical ordering, near 0 indicates random order', 'Correlation between tables', 'Network correlation'], correctAnswer: 1, explanation: 'Correlation measures how well the physical tuple order matches the sorted column values. A correlation of 1.0 means the table is perfectly ordered by that column (ideal for range scans). Near 0 means random order. The planner uses this to estimate the cost of index scans vs sequential scans and to decide on bitmap scans.', codeSnippet: "SELECT attname, correlation\nFROM pg_stats\nWHERE tablename = 'orders';\n\n-- id:         0.99  (sequential inserts, high correlation)\n-- created_at: 0.95  (append-only, nearly ordered)\n-- status:     0.12  (random, low correlation)\n-- customer_id: 0.02  (random, very low correlation)\n\n-- High correlation: index scan is efficient\n-- Low correlation: bitmap scan may be preferred\n\n-- Improve correlation:\nCLUSTER orders USING idx_orders_created_at;", tags: ['admin', 'analyze', 'correlation', 'physical-ordering'] },
  { id: 'pg-admin-l2-068', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What does pg_stat_archiver show?', options: ['File archival statistics', 'Statistics about the WAL archiver process — including count of successful and failed archival operations, last archived WAL file name, and last failure details', 'Archive storage usage', 'Archived query history'], correctAnswer: 1, explanation: 'pg_stat_archiver tracks WAL archival: archived_count (successful archivals), last_archived_wal, last_archived_time, failed_count, and last_failed_wal/time. Monitoring this is critical when using continuous archiving for PITR backup — failed archivals mean gaps in the WAL archive.', codeSnippet: "SELECT\n  archived_count,\n  last_archived_wal,\n  last_archived_time,\n  failed_count,\n  last_failed_wal,\n  last_failed_time\nFROM pg_stat_archiver;\n\n-- Alert on archival failures:\n-- if failed_count > 0, investigate archive_command\n-- Check: SHOW archive_command;\n-- Check: SHOW archive_mode;", tags: ['admin', 'pg-stat', 'archiver', 'wal'] },
  { id: 'pg-admin-l2-069', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'What is the --on-conflict-do-nothing option in pg_dump (PostgreSQL 12+)?', options: ['Ignores all conflicts during dump', 'When combined with --inserts, generates INSERT statements with ON CONFLICT DO NOTHING — useful for restoring data into a table that may already have some rows', 'Prevents dump conflicts', 'Skips locked tables during dump'], correctAnswer: 1, explanation: '--on-conflict-do-nothing adds ON CONFLICT DO NOTHING to INSERT statements (requires --inserts). This prevents errors when restoring into a table that already contains some of the data. Useful for partial data synchronization or incremental loads.', codeSnippet: "# Generate INSERT ... ON CONFLICT DO NOTHING:\npg_dump --inserts --on-conflict-do-nothing \\\n  -t orders mydb > orders_safe.sql\n\n# Generated SQL:\n# INSERT INTO orders (id, amount) VALUES (1, 99.99)\n#   ON CONFLICT DO NOTHING;\n# INSERT INTO orders (id, amount) VALUES (2, 49.99)\n#   ON CONFLICT DO NOTHING;\n\n# Safe to restore even if some rows already exist:\npsql mydb < orders_safe.sql", tags: ['admin', 'backup', 'pg-dump', 'on-conflict'] },
  { id: 'pg-admin-l2-070', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is the BUFFER_USAGE_LIMIT option for VACUUM (PostgreSQL 16+)?', options: ['Limits the buffer pool size', 'Limits the amount of shared buffer pool memory that VACUUM can use — prevents a large VACUUM from evicting hot data from the buffer cache', 'Limits the number of buffers written', 'Limits the WAL buffer usage'], correctAnswer: 1, explanation: 'VACUUM (BUFFER_USAGE_LIMIT size) in PostgreSQL 16+ controls the ring buffer size used by VACUUM. By default, VACUUM uses a 256KB ring buffer to avoid polluting the shared buffer cache. You can increase it for faster vacuuming of large tables or decrease it to minimize cache impact.', codeSnippet: "-- Limit vacuum buffer usage to 128KB:\nVACUUM (BUFFER_USAGE_LIMIT '128kB') large_table;\n\n-- Increase for faster vacuum:\nVACUUM (BUFFER_USAGE_LIMIT '512kB') large_table;\n\n-- Use 0 to use shared buffers directly (no ring buffer):\nVACUUM (BUFFER_USAGE_LIMIT 0) small_table;\n\n-- Default: vacuum_buffer_usage_limit = 256kB\nSHOW vacuum_buffer_usage_limit;", tags: ['admin', 'vacuum', 'buffer-usage-limit', 'performance'] },
  { id: 'pg-admin-l2-071', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What is pg_stat_subscription used for?', options: ['Monitoring magazine subscriptions', 'Shows the status of logical replication subscriptions — including the subscription name, worker PID, last received LSN, and latest errors', 'Managing subscription payments', 'Listing database subscribers'], correctAnswer: 1, explanation: 'pg_stat_subscription shows logical replication subscription workers: subname, pid, received_lsn, last_msg_send_time, last_msg_receipt_time, and latest_end_lsn. This is essential for monitoring logical replication lag and detecting stalled subscriptions.', codeSnippet: "-- Check subscription status:\nSELECT subname, pid,\n  received_lsn, latest_end_lsn,\n  last_msg_send_time, last_msg_receipt_time\nFROM pg_stat_subscription;\n\n-- Check subscription details:\nSELECT subname, subenabled, subconninfo, subslotname\nFROM pg_subscription;", tags: ['admin', 'pg-stat', 'logical-replication', 'subscription'] },
  { id: 'pg-admin-l2-072', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Tablespaces', question: 'How do tablespaces affect replication?', options: ['Tablespaces are not replicated', 'Standby servers must have the same tablespace directories available — streaming replication replicates all data including tablespace contents, so the file system layout must match', 'Only pg_default is replicated', 'Tablespaces are automatically created on standbys'], correctAnswer: 1, explanation: 'Streaming replication replicates all WAL records, including operations on tablespaces. The standby must have the same tablespace directories (or use tablespace_map for remapping). If a tablespace directory is missing on the standby, replication fails. Plan tablespace layouts consistently across primary and standbys.', codeSnippet: "-- On primary:\nCREATE TABLESPACE fast LOCATION '/ssd/pgdata';\n\n-- Standby must have /ssd/pgdata or use remapping:\n-- In recovery.conf or standby.signal:\n-- tablespace_map = '/ssd/pgdata=/standby_ssd/pgdata'\n\n-- Or create same directory on standby:\n-- mkdir -p /ssd/pgdata\n-- chown postgres:postgres /ssd/pgdata", tags: ['admin', 'tablespaces', 'replication', 'standby'] },
  { id: 'pg-admin-l2-073', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'ANALYZE', question: 'Can ANALYZE be run concurrently with other operations?', options: ['No, it blocks all access', 'Yes — ANALYZE takes only a ShareUpdateExclusiveLock which does not block reads, writes, or most DDL operations; it runs concurrently with normal database activity', 'Only with SELECT queries', 'Only on idle tables'], correctAnswer: 1, explanation: 'ANALYZE acquires a ShareUpdateExclusiveLock, which conflicts only with itself, VACUUM FULL, and certain ALTER TABLE operations. Regular DML (SELECT, INSERT, UPDATE, DELETE) and most DDL run concurrently. This makes it safe to run ANALYZE during peak traffic.', codeSnippet: "-- Safe to run during production:\nANALYZE orders;  -- non-blocking\n\n-- Check lock level:\nSELECT locktype, mode, granted\nFROM pg_locks\nWHERE relation = 'orders'::regclass;\n-- mode: ShareUpdateExclusiveLock\n\n-- Conflicts with:\n-- VACUUM FULL (AccessExclusiveLock)\n-- ALTER TABLE ... (some variants)\n-- Another ANALYZE on same table", tags: ['admin', 'analyze', 'locking', 'concurrent'] },
  { id: 'pg-admin-l2-074', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'What does the --if-exists flag do in pg_dump?', options: ['Only dumps if the database exists', 'When used with --clean, adds IF EXISTS to DROP statements to prevent errors when objects do not exist in the target database', 'Checks if backup file exists', 'Skips existing tables during dump'], correctAnswer: 1, explanation: '--if-exists is used with --clean. Without it, DROP TABLE statements will error if the table does not exist in the target database. With --if-exists, the generated statements become DROP TABLE IF EXISTS, making the restore more robust against partial schemas.', codeSnippet: "# Without --if-exists:\npg_dump --clean mydb > backup.sql\n# DROP TABLE orders;  -- ERROR if orders doesn't exist\n\n# With --if-exists:\npg_dump --clean --if-exists mydb > backup.sql\n# DROP TABLE IF EXISTS orders;  -- no error\n\n# Best practice for clean restores:\npg_dump --clean --if-exists --no-owner mydb > backup.sql", tags: ['admin', 'backup', 'pg-dump', 'if-exists'] },
  { id: 'pg-admin-l2-075', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'How do you check the buffer cache contents?', options: ['Use SHOW BUFFERS', 'Install the pg_buffercache extension to query which relations occupy shared buffer cache pages — useful for understanding cache utilization per table', 'Check /proc/meminfo', 'Use pg_stat_bgwriter only'], correctAnswer: 1, explanation: 'pg_buffercache extension provides a view of the shared buffer cache contents. Each row represents a buffer page, showing which relation occupies it, whether it is dirty (modified), and its usage count. This helps understand which tables benefit most from the buffer cache.', codeSnippet: "CREATE EXTENSION pg_buffercache;\n\n-- Buffer cache usage per table:\nSELECT c.relname,\n  count(*) AS buffers,\n  pg_size_pretty(count(*) * 8192) AS cached_size,\n  round(100.0 * count(*) /\n    (SELECT count(*) FROM pg_buffercache), 2) AS cache_pct\nFROM pg_buffercache b\nJOIN pg_class c ON b.relfilenode = pg_relation_filenode(c.oid)\nWHERE b.reldatabase = (SELECT oid FROM pg_database WHERE datname = current_database())\nGROUP BY c.relname\nORDER BY buffers DESC\nLIMIT 20;", tags: ['admin', 'pg-stat', 'buffer-cache', 'pg-buffercache'] },
  { id: 'pg-admin-l2-076', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is the difference between dead tuples and recently dead tuples?', options: ['They are the same thing', 'Dead tuples are no longer visible to any transaction and can be vacuumed; recently dead tuples are obsolete but still visible to some active transactions and cannot be removed yet', 'Recently dead tuples are from the last hour', 'Dead tuples are in deleted tables'], correctAnswer: 1, explanation: 'A tuple becomes dead when no active transaction can see it anymore (based on the global xmin horizon). Recently dead tuples are from completed transactions but some active transaction still has a snapshot that includes them. VACUUM can only reclaim fully dead tuples, not recently dead ones.', codeSnippet: "-- Check dead vs recently dead:\nVACUUM VERBOSE orders;\n-- ... tuples: 500 removed, 100000 remain,\n-- 200 are dead but not yet removable\n-- ^^^ recently dead (held by active transactions)\n\n-- Find what's holding tuples back:\nSELECT pid, xact_start, state\nFROM pg_stat_activity\nWHERE backend_xmin IS NOT NULL\nORDER BY age(backend_xmin) DESC;", tags: ['admin', 'vacuum', 'dead-tuples', 'xmin'] },
  { id: 'pg-admin-l2-077', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'What is pg_verifybackup (PostgreSQL 13+)?', options: ['Verifies database integrity', 'A tool that validates a physical backup taken with pg_basebackup by checking file checksums against the backup manifest', 'Verifies logical backup integrity', 'Verifies replication consistency'], correctAnswer: 1, explanation: 'pg_verifybackup verifies the integrity of a backup taken with pg_basebackup --manifest-checksums. It checks that all files listed in the manifest exist, have the correct size, and match their recorded checksums. This provides backup verification without performing a full restore.', codeSnippet: "# Take backup with manifest:\npg_basebackup -D /backup/base -Fp -Xs -P\n\n# Verify backup integrity:\npg_verifybackup /backup/base\n\n# Verify with specific algorithm:\npg_verifybackup --manifest-path=/backup/base/backup_manifest /backup/base\n\n# Output on success:\n# backup successfully verified", tags: ['admin', 'backup', 'verification', 'pg-verifybackup'] },
  { id: 'pg-admin-l2-078', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What does pg_stat_ssl show?', options: ['SSL certificate information', 'Shows SSL connection status for each backend — including whether SSL is used, the protocol version, cipher, and whether the client authenticated with a certificate', 'SSL configuration settings', 'SSL performance metrics'], correctAnswer: 1, explanation: 'pg_stat_ssl (joined with pg_stat_activity) shows which connections use SSL, the SSL version (TLSv1.2, TLSv1.3), cipher suite, key bits, and whether client certificates are used. Essential for verifying encryption compliance in security audits.', codeSnippet: "-- Check SSL status of connections:\nSELECT a.pid, a.usename, a.client_addr,\n  s.ssl, s.version AS ssl_version,\n  s.cipher, s.bits,\n  s.client_dn AS client_cert\nFROM pg_stat_activity a\nJOIN pg_stat_ssl s ON a.pid = s.pid\nWHERE a.datname = current_database();\n\n-- Verify all connections use SSL:\nSELECT ssl, count(*)\nFROM pg_stat_ssl\nGROUP BY ssl;", tags: ['admin', 'pg-stat', 'ssl', 'security'] },
  { id: 'pg-admin-l2-079', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'Can you run VACUUM on specific columns?', options: ['Yes, VACUUM can target specific columns', 'No — VACUUM operates on entire tables (or the entire database); you cannot vacuum specific columns because dead tuples are row-level, not column-level', 'Only on TOAST columns', 'Only on indexed columns'], correctAnswer: 1, explanation: 'VACUUM works at the tuple (row) level. A dead tuple means the entire row is dead. There is no concept of column-level dead data in PostgreSQL\'s heap storage. ANALYZE, however, can target specific columns: ANALYZE table (column1, column2).', codeSnippet: "-- VACUUM: entire table only\nVACUUM orders;  -- OK\n-- VACUUM orders (amount);  -- ERROR: not supported\n\n-- ANALYZE: can target specific columns\nANALYZE orders (status, amount);  -- OK\n\n-- VACUUM the whole database:\nVACUUM;", tags: ['admin', 'vacuum', 'columns', 'limitations'] },
  { id: 'pg-admin-l2-080', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Tablespaces', question: 'How does the temp_tablespaces setting work?', options: ['It creates temporary tablespaces', 'Specifies tablespaces for temporary tables and sort files — PostgreSQL round-robins across the listed tablespaces, spreading I/O for temp operations across multiple disks', 'Temporary tablespace cleanup setting', 'Controls temp table retention'], correctAnswer: 1, explanation: 'temp_tablespaces is a comma-separated list of tablespaces used for temporary objects and sort/hash operations that exceed work_mem. PostgreSQL selects from the list round-robin style, distributing temp I/O across multiple tablespaces/disks. This can significantly improve sort and hash join performance.', codeSnippet: "-- Set temp tablespaces:\nSET temp_tablespaces = 'temp_ssd1, temp_ssd2';\n\n-- Or permanently:\nALTER DATABASE mydb SET temp_tablespaces = 'temp_ssd1, temp_ssd2';\n\n-- Check current setting:\nSHOW temp_tablespaces;\n\n-- Temp operations now round-robin across both SSDs:\nCREATE TEMP TABLE big_sort AS\nSELECT * FROM large_table ORDER BY random();", tags: ['admin', 'tablespaces', 'temp', 'performance'] },
  { id: 'pg-admin-l2-081', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'ANALYZE', question: 'What is the pg_stat_all_tables.n_mod_since_analyze column?', options: ['Number of modifications to statistics', 'Count of row modifications (inserts + updates + deletes) since the last ANALYZE — autovacuum compares this against thresholds to decide when to auto-analyze', 'Number of schema modifications', 'Number of modifiers (users who changed data)'], correctAnswer: 1, explanation: 'n_mod_since_analyze tracks how many rows have been modified since the last ANALYZE. Autovacuum uses this: when n_mod_since_analyze > threshold + scale_factor * reltuples, it triggers auto-analyze. Monitoring this helps identify tables with stale statistics.', codeSnippet: "-- Tables with most modifications since last analyze:\nSELECT relname,\n  n_mod_since_analyze,\n  n_live_tup,\n  last_analyze, last_autoanalyze,\n  round(100.0 * n_mod_since_analyze / NULLIF(n_live_tup, 0), 1)\n    AS mod_pct\nFROM pg_stat_user_tables\nWHERE n_mod_since_analyze > 0\nORDER BY n_mod_since_analyze DESC;", tags: ['admin', 'analyze', 'n-mod-since-analyze', 'autovacuum'] },
  { id: 'pg-admin-l2-082', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What does the wait_event column in pg_stat_activity indicate?', options: ['How long a query has been waiting', 'The specific event a backend process is currently waiting on — such as I/O operations, locks, buffer operations, or client communication', 'Whether the query is in a wait state', 'The next scheduled event'], correctAnswer: 1, explanation: 'wait_event shows what a process is currently waiting for (if anything). Combined with wait_event_type (Activity, BufferPin, Client, Extension, IO, IPC, Lock, LWLock, Timeout), it helps identify bottlenecks: frequent IO waits indicate disk issues, Lock waits indicate contention.', codeSnippet: "-- Check what processes are waiting on:\nSELECT pid, state,\n  wait_event_type, wait_event,\n  query\nFROM pg_stat_activity\nWHERE wait_event IS NOT NULL;\n\n-- Common wait events:\n-- IO/DataFileRead - reading from disk (needs more RAM)\n-- Lock/relation - waiting for table lock\n-- Client/ClientRead - waiting for client input\n-- LWLock/BufferContent - buffer lock contention\n\n-- Wait event distribution:\nSELECT wait_event_type, wait_event, count(*)\nFROM pg_stat_activity\nWHERE wait_event IS NOT NULL\nGROUP BY 1, 2 ORDER BY 3 DESC;", tags: ['admin', 'pg-stat', 'wait-events', 'bottlenecks'] },
  { id: 'pg-admin-l2-083', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'How do you handle backup of large objects (BLOBs)?', options: ['Large objects are always included in backups', 'pg_dump includes large objects by default; use --no-blobs to exclude them, or --blobs to explicitly include them; large objects are stored in the pg_largeobject catalog', 'Large objects must be backed up separately', 'Large objects cannot be backed up'], correctAnswer: 1, explanation: 'pg_dump includes large objects (pg_largeobject entries) by default. The --no-blobs flag excludes them, which can significantly reduce dump size if the database has many large objects. --blobs (default) explicitly includes them. Large objects are stored in a system catalog, not in regular tables.', codeSnippet: "# Default: includes large objects\npg_dump mydb > backup.sql\n\n# Exclude large objects:\npg_dump --no-blobs mydb > backup_no_blobs.sql\n\n# Check large object sizes:\nSELECT count(*) AS num_objects,\n  pg_size_pretty(sum(octet_length(data))) AS total_size\nFROM pg_largeobject;", tags: ['admin', 'backup', 'large-objects', 'blobs'] },
  { id: 'pg-admin-l2-084', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is the SKIP_LOCKED option for VACUUM?', options: ['Skips locked tables entirely', 'VACUUM (SKIP_LOCKED) skips relations that cannot be immediately locked — useful for scripted maintenance that should not block or be blocked by concurrent activity', 'Ignores row-level locks', 'Unlocks locked rows'], correctAnswer: 1, explanation: 'VACUUM (SKIP_LOCKED) (PostgreSQL 12+) attempts to lock each table but skips any that are already locked instead of waiting. This is useful for maintenance scripts that vacuum multiple tables: rather than blocking on a locked table, it moves on and the skipped table can be vacuumed later.', codeSnippet: "-- Skip tables that are locked:\nVACUUM (SKIP_LOCKED, VERBOSE);\n\n-- Combined with ANALYZE:\nVACUUM (SKIP_LOCKED, ANALYZE, VERBOSE);\n\n-- Useful in maintenance scripts:\n-- Run vacuum across all tables without blocking\n-- Retry skipped tables later\n\n-- ANALYZE also supports SKIP_LOCKED:\nANALYZE (SKIP_LOCKED, VERBOSE);", tags: ['admin', 'vacuum', 'skip-locked', 'maintenance'] },
  { id: 'pg-admin-l2-085', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'What is pg_stat_user_functions used for?', options: ['Lists function definitions', 'Shows execution statistics for tracked functions — including call count, total execution time, and self time (excluding time in nested function calls)', 'Shows function permissions', 'Lists function dependencies'], correctAnswer: 1, explanation: 'pg_stat_user_functions tracks: calls (invocation count), total_time (including time in called functions), and self_time (excluding nested calls). Requires track_functions = \'pl\' (PL/pgSQL only) or \'all\' (all languages). Essential for identifying slow functions.', codeSnippet: "-- Enable function tracking:\n-- postgresql.conf: track_functions = 'all'\n\n-- Check function performance:\nSELECT funcname, calls,\n  round(total_time::numeric, 2) AS total_ms,\n  round(self_time::numeric, 2) AS self_ms,\n  round((total_time / NULLIF(calls, 0))::numeric, 2) AS avg_ms\nFROM pg_stat_user_functions\nORDER BY total_time DESC;", tags: ['admin', 'pg-stat', 'functions', 'performance'] },
  { id: 'pg-admin-l2-086', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'Backup Strategies', question: 'What is the --snapshot option in pg_dump?', options: ['Takes a snapshot of the dump progress', 'Allows multiple pg_dump processes to share the same database snapshot — ensuring all dumps see a consistent point-in-time view of the data', 'Creates a snapshot of the database', 'Takes a file system snapshot'], correctAnswer: 1, explanation: '--snapshot allows multiple pg_dump invocations to share the same transaction snapshot, ensuring consistency across dumps. This is useful when dumping different schemas or tables in parallel from separate pg_dump processes while maintaining a single consistent view.', codeSnippet: "# Export a snapshot:\npg_dump --snapshot=00000003-0000001A-1 \\\n  -t schema1.* mydb > schema1.sql &\n\npg_dump --snapshot=00000003-0000001A-1 \\\n  -t schema2.* mydb > schema2.sql &\n\n# Both dumps see the same consistent state\n\n# Get snapshot ID from a transaction:\nBEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ;\nSELECT pg_export_snapshot();\n-- Returns: 00000003-0000001A-1", tags: ['admin', 'backup', 'snapshot', 'consistency'] },
  { id: 'pg-admin-l2-087', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'VACUUM', question: 'What is the PROCESS_TOAST option for VACUUM?', options: ['Enables toast notifications', 'Controls whether VACUUM processes the TOAST table associated with the main table — PROCESS_TOAST OFF skips TOAST vacuuming for faster main-table cleanup', 'Processes toasted (compressed) data', 'A notification mechanism'], correctAnswer: 1, explanation: 'VACUUM (PROCESS_TOAST OFF) (PostgreSQL 14+) skips vacuuming of the associated TOAST table. TOAST tables can be very large for tables with many large text/bytea values. Skipping TOAST processing makes the main table vacuum faster when TOAST cleanup is not urgent.', codeSnippet: "-- Skip TOAST table processing:\nVACUUM (PROCESS_TOAST OFF) documents;\n\n-- Check TOAST table size:\nSELECT c.relname AS main_table,\n  t.relname AS toast_table,\n  pg_size_pretty(pg_relation_size(t.oid)) AS toast_size\nFROM pg_class c\nJOIN pg_class t ON t.oid = c.reltoastrelid\nWHERE c.relname = 'documents';", tags: ['admin', 'vacuum', 'toast', 'optimization'] },
  { id: 'pg-admin-l2-088', language: 'postgresql', level: 'level2', category: 'Administration', subcategory: 'pg_stat Views', question: 'How do you monitor temporary file usage?', options: ['Check /tmp directory', 'Use pg_stat_database for aggregate temp file stats, and log_temp_files setting to log creation of temp files exceeding a threshold — temp files indicate work_mem overflow', 'Use pg_stat_temp_files', 'Check pg_stat_activity.temp_usage'], correctAnswer: 1, explanation: 'pg_stat_database shows temp_files and temp_bytes per database. Setting log_temp_files = 0 logs all temp file creation. Higher values log only files exceeding that size in KB. Frequent large temp files indicate work_mem should be increased or queries need optimization.', codeSnippet: "-- Check temp file usage per database:\nSELECT datname, temp_files, temp_bytes,\n  pg_size_pretty(temp_bytes) AS temp_size\nFROM pg_stat_database\nWHERE temp_files > 0;\n\n-- Enable logging of temp files:\nSET log_temp_files = 0;  -- log all temp files\n-- Or: SET log_temp_files = 1024;  -- log files > 1MB\n\n-- Increase work_mem to reduce temp files:\nSET work_mem = '256MB';  -- per-sort/hash operation", tags: ['admin', 'pg-stat', 'temp-files', 'work-mem'] },
];

